type Hill = ReturnType<typeof buildHill>
const edgesByHill = new WeakMap<Hill, Map<number, number>>()
function edgeTick(hill: Hill, gate: number): number {
  let edges = edgesByHill.get(hill); if (!edges) { edges = new Map(); edgesByHill.set(hill, edges) }
  const c = edges.get(gate); if (c !== undefined) return c
  const sim = new JumpSimulation({ hill, gateNumber: gate, autoStart: true })
  while (sim.phase === 'Inrun' || sim.phase === 'Takeoff') sim.step(EMPTY_INPUT)
  edges.set(gate, sim.tick); return sim.tick
}
type Trial = { gate: number; wind: number; offset?: number; prep?: number; style?: 'parallel' | 'telemark' | null; aoa?: number; windField?: WindField }
function run(hill: Hill, trial: Trial): JumpSimulation {
  const wf = { seed: 42, version: 'h04-constant-wind-v1', sampleUserMetersPerSecond: () => trial.wind } as WindField
  const sim = new JumpSimulation({ hill, gateNumber: trial.gate, windField: trial.windField ?? wf, autoStart: true })
  const takeoffTick = edgeTick(hill, trial.gate) - Math.round(DEFAULT_JUMP_PARAMS.takeoff.idealLeadSeconds / SIM_DT) + (trial.offset ?? 0)
  let prepped = false
  for (let g = 0; g < 20000 && !sim.finished; g++) {
    const pressed: ('takeoff' | 'telemark' | 'parallel')[] = []; const held: ('left' | 'right')[] = []
    if (sim.tick === takeoffTick) pressed.push('takeoff')
    if (sim.phase === 'Flight') {
      const desired = Math.atan2(sim.velocity.y, sim.velocity.x) * 180 / Math.PI + (trial.aoa ?? 32)
      const cur = sim.targetPitchRad * 180 / Math.PI
      if (cur > desired + 0.5) held.push('right'); else if (cur < desired - 0.5) held.push('left')
      if (!prepped && trial.style !== null && sim.flightSeconds >= (trial.prep ?? 5)) { pressed.push(trial.style ?? 'parallel'); prepped = true }
    }
    sim.step(makeInput(pressed, held, sim.tick))
  }
