}
// Browser-like pilot: lagged snapshot, periodic key decisions, flow+aoa, R at 5 s or (3 s and h<=1.6).
function browserPilot(hill: Hill, gate: number, field: WindField, offset: number, lag: number, period: number, aoa = 29): JumpSimulation {
  const sim = new JumpSimulation({ hill, gateNumber: gate, windField: field, autoStart: true })
  const takeoffTick = edgeTick(hill, gate) - Math.round(DEFAULT_JUMP_PARAMS.takeoff.idealLeadSeconds / SIM_DT) + offset
  const hist: { phase: string; flow: number; target: number; fs: number; h: number }[] = []
  let held: 'left' | 'right' | null = null; let sent = false; let pendingLanding = -1
  for (let g = 0; g < 20000 && !sim.finished; g++) {
    hist.push({ phase: sim.phase, flow: Math.atan2(sim.velocity.y, sim.velocity.x) * 180 / Math.PI, target: sim.targetPitchRad * 180 / Math.PI, fs: sim.flightSeconds, h: sim.phase === 'Flight' ? sim.heightAboveSurface() : 99 })
    const pressed: ('takeoff' | 'parallel')[] = []
    if (sim.tick === takeoffTick) pressed.push('takeoff')
    const seen = hist[Math.max(0, hist.length - 1 - lag)]!
    if (sim.tick % period === 0 && seen.phase === 'Flight' && !sent) {
      const desired = seen.flow + aoa
      held = seen.target > desired + 0.5 ? 'right' : seen.target < desired - 0.5 ? 'left' : null
      if (seen.fs >= 5 || (seen.fs >= 3 && seen.h <= 1.6)) { held = null; sent = true; pendingLanding = sim.tick + 1 }
    }
    if (sim.tick === pendingLanding && sim.phase === 'Flight') pressed.push('parallel')
    sim.step(makeInput(pressed, held ? [held] : [], sim.tick))
  }
  return sim
}
function sweep(hill: Hill) {
  const samples = [...Array.from({ length: 33 }, (_, i) => (i - 16) / 5), -0.01, 0.01, -0.0001, 0.0001]
  let prev = selectSafeJuryGate(hill, -3.2).gateNumber; const switches: number[] = []
