  for (const b of switches) for (const d of [-0.002, 0, 0.002]) { const w = b + d; if (w > -3.2 && w < 3.2) samples.push(w) }
  const full = new Set([0, -0.0001, 0.0001, ...switches.flatMap(w => [w - 0.001, w])])
  let wt = 0, wh = 0, wtAt = '', whAt = ''
