    const raw = Math.max(...trials.map(s => s.measuredDistanceMeters ?? 0))
    if (wind < 0 && raw > wt) { wt = raw; wtAt = `g${gate} w${wind}` }
    if (wind >= 0 && raw > wh) { wh = raw; whAt = `g${gate} w${wind}` }
  }
