  for (const lag of [2, 3]) for (const period of [2, 3]) for (const offset of [-4, -2, 0, 2, 4]) {
    const s = browserPilot(hill, cGate, field, offset, lag, period)
    comp.push(s.outcome?.status === 'landed' ? (s.measuredDistanceMeters ?? 0) : 0)
  }
  comp.sort((a, b) => a - b)
  const nominal = run(hill, { gate: 6, wind: 0, prep: 5 })
  const nominal28 = run(hill, { gate: 6, wind: 0, prep: 5, aoa: 28 })
  const strong = run(hill, { gate: 1, wind: 3.2, aoa: 28, prep: 5 })
  const rec = run(hill, { gate: 42, wind: 0, prep: 5 })
  const out = {
    label, compGate: cGate, forecast: forecastWindMean(field, hill).toFixed(2),
    comp: { min: comp[0]!.toFixed(1), med: comp[Math.floor(comp.length / 2)]!.toFixed(1), max: comp.at(-1)!.toFixed(1), n: comp.length, below180: comp.filter(d => d < 180).length },
    nominal: `${nominal.outcome?.status} ${nominal.measuredDistanceMeters?.toFixed(2)}`,
    nominal28: `${nominal28.outcome?.status} ${nominal28.measuredDistanceMeters?.toFixed(2)}`,
